create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'customer' check (role in ('admin','customer')), created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, display_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories(id), name text not null, slug text not null unique, description text not null default '', pack_size text not null, price numeric(10,2) not null check(price>=0), stock_quantity integer not null default 0 check(stock_quantity>=0), image_url text, badge text, is_featured boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create policy "categories public" on public.categories for select using(is_active or public.is_admin()); create policy "products public" on public.products for select using(is_active or public.is_admin()); create policy "admins categories" on public.categories for all using(public.is_admin()) with check(public.is_admin()); create policy "admins products" on public.products for all using(public.is_admin()) with check(public.is_admin()); create policy "own profile" on public.profiles for select using(auth.uid()=id);
